const h=document.documentElement.outerHTML; const src=(h.match(/https:\/\/proxy\.whatships\.com\/\?url=[^"'\s<>)]+/)||[])[0].replace(/&amp;/g,'&'); document.querySelectorAll('video').forEach(x=>x.remove()); document.documentElement.style.overflow='hidden'; document.body.style.overflow='hidden';
const v=document.createElement('video'); v.id='wsv'; v.crossOrigin='anonymous'; v.muted=true; v.playsInline=true; v.preload='auto'; v.src=src; v.style.cssText='position:fixed;left:-9999px;width:640px;height:360px'; document.body.appendChild(v);
const c=document.createElement('canvas'); c.id='wsc'; c.width=1024; c.height=576; Object.assign(c.style,{position:'fixed',left:'0',top:'96px',width:'1024px',height:'576px',zIndex:'100000',background:'#000'}); document.body.appendChild(c);
window.show = async (t)=>{const v=document.getElementById('wsv'); v.pause(); await new Promise(res=>{const f=()=>{v.removeEventListener('seeked',f);res()}; v.addEventListener('seeked',f); v.currentTime=t; setTimeout(res,6000)}); await new Promise(res=>{ if(v.requestVideoFrameCallback){v.requestVideoFrameCallback(()=>res()); setTimeout(res,800)} else setTimeout(res,400)}); await new Promise(r=>setTimeout(r,150)); const c=document.getElementById('wsc'); const x=c.getContext('2d'); x.drawImage(v,0,0,c.width,c.height); x.fillStyle='rgba(0,0,0,.6)'; x.fillRect(0,0,70,20); x.fillStyle='#0f0'; x.font='14px monospace'; x.fillText('t='+v.currentTime.toFixed(1),4,14); return v.currentTime};
window.analyzeAudio = async (ab, step=0.25)=>{ const ctx=new (window.OfflineAudioContext||window.webkitOfflineAudioContext)(1,44100,44100); const buf=await ctx.decodeAudioData(ab.slice(0)); const ch=buf.getChannelData(0); const sr=buf.sampleRate; const n=Math.floor(ch.length/(sr*step)); const rms=[]; const zc=[]; for(let i=0;i<n;i++){let s=0,z=0;const a=Math.floor(i*sr*step),b=Math.floor((i+1)*sr*step); for(let j=a;j<b;j++){s+=ch[j]*ch[j]; if(j>a && (ch[j]>=0)!=(ch[j-1]>=0)) z++;} rms.push(Math.sqrt(s/(b-a))); zc.push(z/(b-a)*sr/2);} return {dur:buf.duration, sr, ch:buf.numberOfChannels, rms:rms.map(x=>+(x*100).toFixed(1)), zcHz:zc.map(x=>Math.round(x))}};
await new Promise(res=>{v.addEventListener('loadedmetadata',res,{once:true}); setTimeout(res,8000)}); JSON.stringify({src,dur:v.duration,w:v.videoWidth,h:v.videoHeight})

